insert into public.guides (agency_id, slug, title, audience, language, services, content, version, is_published) values
(1, 'trafego', 'Como funciona: tráfego pago', 'cliente', 'pt', array['Tráfego Pago']::text[], '{"hero": {"eyebrow": "Bolsa · Guia do cliente", "title": "Seus anúncios, do primeiro clique à venda.", "text": "Este guia mostra como acompanhar os anúncios, aprovar as peças e registrar os contatos no Bolsa. Tudo pelo celular."}, "steps": [{"title": "Portal", "who": "Você", "tone": "cliente"}, {"title": "Tráfego", "who": "Você", "tone": "cliente"}, {"title": "Aprovar anúncios", "who": "Você", "tone": "cliente"}, {"title": "CRM", "who": "Você", "tone": "cliente"}], "sections": [{"who": "Você", "tone": "cliente", "title": "Seu portal: tudo do seu marketing num lugar só", "text": "Você recebe um link e um login. Pelo celular ou pelo computador, o Bolsa mostra o que está esperando você, o que está em produção e o que já foi publicado.", "images": [{"src": "/guias/clientes/canguru/home.jpg", "alt": "Tela inicial do portal com o que falta aprovar", "frame": "phone"}, {"src": "/guias/clientes/canguru/menu.jpg", "alt": "Menu do portal com todas as áreas", "frame": "phone"}], "layout": "stack", "bullets": ["Na tela inicial, o número laranja é o que está esperando a sua aprovação. Comece sempre por ali.", "O menu (no canto de cima) leva para cada área. Você só vê as áreas do que contratou.", "Salve o link na tela inicial do celular. Fica como um aplicativo."]}, {"who": "Você", "tone": "cliente", "title": "Tráfego pago: quanto investimos e o que voltou", "text": "Em Tráfego Pago você acompanha os anúncios do Meta (Instagram e Facebook) e do Google sem precisar entrar em nenhuma das duas plataformas.", "images": [{"src": "/guias/clientes/canguru/trafego.jpg", "alt": "Painel de tráfego com verba, investimento e resultados", "frame": "phone"}, {"src": "/guias/clientes/canguru/trafego-plataformas.jpg", "alt": "Gráfico diário e números por plataforma", "frame": "phone"}], "layout": "stack", "bullets": ["Consumo da verba: quanto da verba do mês já foi usada e quanto falta.", "Investimento, resultados (contatos no WhatsApp e formulários), cliques e impressões, sempre comparando com o período anterior.", "Custo por resultado: quanto custou cada contato. É o número mais importante para saber se o anúncio vale a pena.", "Escolha 7, 30 ou 90 dias e veja cada plataforma separada."]}, {"who": "Você", "tone": "cliente", "title": "Aprovar os anúncios leva um minuto por peça", "text": "Antes de qualquer anúncio ir ao ar, você aprova. As peças chegam em Criativos ou por um link no WhatsApp.", "images": [{"src": "/guias/clientes/canguru/criativos-capa.jpg", "alt": "Campanha com as peças para aprovar", "frame": "phone"}, {"src": "/guias/clientes/canguru/criativo-peca.jpg", "alt": "Uma peça com os botões Aprovar e Pedir ajuste", "frame": "phone"}, {"src": "/guias/clientes/canguru/criativo-ajuste.jpg", "alt": "Pedido de ajuste com sugestões prontas", "frame": "phone"}], "layout": "stack", "bullets": ["Toque em Começar a revisão. Abre uma peça por vez, com a imagem e o texto do anúncio.", "Gostou? Aprovar. A próxima abre sozinha.", "Quer mudar algo? Pedir ajuste, escolha o que mudar (imagem, texto, cores, chamada) e escreva em uma frase.", "A equipe recebe na hora e manda a nova versão para você aprovar de novo."]}, {"who": "Você", "tone": "cliente", "title": "CRM: anote cada contato que chegou", "text": "Os anúncios trazem contatos. O CRM mostra quantos viraram venda. É com isso que a gente sabe qual anúncio dá dinheiro e qual só dá clique.", "images": [{"src": "/guias/clientes/canguru/crm-kanban.jpg", "alt": "Funil de contatos do CRM com as etapas", "frame": "phone"}], "layout": "image-left", "bullets": ["Cada contato é um cartão: nome, telefone, origem e o interesse.", "Mova o cartão conforme a conversa anda: novo, em conversa, proposta enviada, fechado ou perdido.", "Fechou? Coloque o valor. Perdeu? Marque o motivo. Leva segundos e muda a estratégia do mês seguinte.", "Em Relatório você vê contatos do mês, fechamentos, taxa de conversão e o dinheiro em negociação."]}, {"who": "Juntos", "tone": "equipe", "dark": true, "title": "O combinado para dar certo", "text": "Quanto mais rápido você responde, mais rápido as coisas vão ao ar. Qualquer dúvida, fale com a Canguru pelo WhatsApp.", "cards": [{"title": "Aprove rápido", "text": "O que espera você aparece em laranja na tela inicial."}, {"title": "Anote os contatos", "text": "CRM em dia é anúncio melhor no mês seguinte."}, {"title": "Mande material", "text": "Fotos e vídeos reais do seu negócio deixam tudo mais forte."}]}]}'::jsonb, 1, true),
(1, 'trafego-e-redes', 'Como funciona: tráfego pago e redes sociais', 'cliente', 'pt', array['Tráfego Pago','Social Media']::text[], '{"hero": {"eyebrow": "Bolsa · Guia do cliente", "title": "Anúncios e redes sociais, num lugar só.", "text": "Este guia mostra como aprovar posts e anúncios, acompanhar os resultados e registrar os contatos no Bolsa."}, "steps": [{"title": "Portal", "who": "Você", "tone": "cliente"}, {"title": "Posts", "who": "Você", "tone": "cliente"}, {"title": "Anúncios", "who": "Você", "tone": "cliente"}, {"title": "Resultados", "who": "Você", "tone": "cliente"}, {"title": "CRM", "who": "Você", "tone": "cliente"}], "sections": [{"who": "Você", "tone": "cliente", "title": "Seu portal: tudo do seu marketing num lugar só", "text": "Você recebe um link e um login. Pelo celular ou pelo computador, o Bolsa mostra o que está esperando você, o que está em produção e o que já foi publicado.", "images": [{"src": "/guias/clientes/canguru/home.jpg", "alt": "Tela inicial do portal com o que falta aprovar", "frame": "phone"}, {"src": "/guias/clientes/canguru/menu.jpg", "alt": "Menu do portal com todas as áreas", "frame": "phone"}], "layout": "stack", "bullets": ["Na tela inicial, o número laranja é o que está esperando a sua aprovação. Comece sempre por ali.", "O menu (no canto de cima) leva para cada área. Você só vê as áreas do que contratou.", "Salve o link na tela inicial do celular. Fica como um aplicativo."]}, {"who": "Você", "tone": "cliente", "title": "Painel de Conteúdo: o calendário dos seus posts", "text": "Todo post planejado para o mês aparece aqui, com data, formato e situação.", "images": [{"src": "/guias/clientes/canguru/conteudo-mapa.jpg", "alt": "Mapa do mês com as legendas de situação", "frame": "phone"}, {"src": "/guias/clientes/canguru/conteudo-lista.jpg", "alt": "Lista de posts do mês com a situação de cada um", "frame": "phone"}], "layout": "stack", "bullets": ["As cores dizem a situação: em produção, esperando aprovação, ajustes solicitados, aprovado, programado e publicado.", "Os laranjas são os que esperam você.", "Use as setas para ver o mês seguinte assim que ele for liberado."]}, {"who": "Você", "tone": "cliente", "title": "Aprovar um post", "text": "Toque no post. Você vê exatamente como ele vai ficar no Instagram, com a legenda.", "images": [{"src": "/guias/clientes/canguru/post-preview.jpg", "alt": "Prévia do post como vai aparecer no Instagram", "frame": "phone"}, {"src": "/guias/clientes/canguru/post-aprovar.jpg", "alt": "Botões Aprovar, Ajuste e Reprovar", "frame": "phone"}], "layout": "stack", "bullets": ["Em Detalhes ficam os botões: Aprovar, Ajuste ou Reprovar.", "Pediu ajuste? Escreva o que mudar nos comentários do post. A conversa fica guardada ali, sem se perder no WhatsApp.", "O histórico mostra cada versão e quem aprovou."]}, {"who": "Você", "tone": "cliente", "title": "Aprovar os anúncios leva um minuto por peça", "text": "Antes de qualquer anúncio ir ao ar, você aprova. As peças chegam em Criativos ou por um link no WhatsApp.", "images": [{"src": "/guias/clientes/canguru/criativos-capa.jpg", "alt": "Campanha com as peças para aprovar", "frame": "phone"}, {"src": "/guias/clientes/canguru/criativo-peca.jpg", "alt": "Uma peça com os botões Aprovar e Pedir ajuste", "frame": "phone"}, {"src": "/guias/clientes/canguru/criativo-ajuste.jpg", "alt": "Pedido de ajuste com sugestões prontas", "frame": "phone"}], "layout": "stack", "bullets": ["Toque em Começar a revisão. Abre uma peça por vez, com a imagem e o texto do anúncio.", "Gostou? Aprovar. A próxima abre sozinha.", "Quer mudar algo? Pedir ajuste, escolha o que mudar (imagem, texto, cores, chamada) e escreva em uma frase.", "A equipe recebe na hora e manda a nova versão para você aprovar de novo."]}, {"who": "Você", "tone": "cliente", "title": "Tráfego pago: quanto investimos e o que voltou", "text": "Em Tráfego Pago você acompanha os anúncios do Meta (Instagram e Facebook) e do Google sem precisar entrar em nenhuma das duas plataformas.", "images": [{"src": "/guias/clientes/canguru/trafego.jpg", "alt": "Painel de tráfego com verba, investimento e resultados", "frame": "phone"}, {"src": "/guias/clientes/canguru/trafego-plataformas.jpg", "alt": "Gráfico diário e números por plataforma", "frame": "phone"}], "layout": "stack", "bullets": ["Consumo da verba: quanto da verba do mês já foi usada e quanto falta.", "Investimento, resultados (contatos no WhatsApp e formulários), cliques e impressões, sempre comparando com o período anterior.", "Custo por resultado: quanto custou cada contato. É o número mais importante para saber se o anúncio vale a pena.", "Escolha 7, 30 ou 90 dias e veja cada plataforma separada."]}, {"who": "Você", "tone": "cliente", "title": "Redes sociais: como o perfil está crescendo", "text": "Os números do Instagram são coletados todos os dias e aparecem em Redes Sociais.", "images": [{"src": "/guias/clientes/canguru/redes.jpg", "alt": "Painel de redes sociais com alcance, impressões, engajamento e seguidores", "frame": "phone"}], "layout": "image-left", "bullets": ["Alcance: quantas pessoas viram seu conteúdo.", "Engajamento: curtidas, comentários, compartilhamentos e salvos.", "Novos seguidores no período, comparando com o período anterior.", "O gráfico mostra dia a dia o que funcionou melhor."]}, {"who": "Você", "tone": "cliente", "title": "CRM: anote cada contato que chegou", "text": "Os anúncios trazem contatos. O CRM mostra quantos viraram venda. É com isso que a gente sabe qual anúncio dá dinheiro e qual só dá clique.", "images": [{"src": "/guias/clientes/canguru/crm-kanban.jpg", "alt": "Funil de contatos do CRM com as etapas", "frame": "phone"}], "layout": "image-left", "bullets": ["Cada contato é um cartão: nome, telefone, origem e o interesse.", "Mova o cartão conforme a conversa anda: novo, em conversa, proposta enviada, fechado ou perdido.", "Fechou? Coloque o valor. Perdeu? Marque o motivo. Leva segundos e muda a estratégia do mês seguinte.", "Em Relatório você vê contatos do mês, fechamentos, taxa de conversão e o dinheiro em negociação."]}, {"who": "Juntos", "tone": "equipe", "dark": true, "title": "O combinado para dar certo", "text": "Quanto mais rápido você responde, mais rápido as coisas vão ao ar. Qualquer dúvida, fale com a Canguru pelo WhatsApp.", "cards": [{"title": "Aprove rápido", "text": "O que espera você aparece em laranja na tela inicial."}, {"title": "Anote os contatos", "text": "CRM em dia é anúncio melhor no mês seguinte."}, {"title": "Mande material", "text": "Fotos e vídeos reais do seu negócio deixam tudo mais forte."}]}]}'::jsonb, 1, true),
